CREATE TABLE paper_accounts (id TEXT PRIMARY KEY, strategy TEXT NOT NULL UNIQUE CHECK(strategy IN ('automatic','approval')), starting_balance REAL NOT NULL CHECK(starting_balance>0), cash_balance REAL NOT NULL CHECK(cash_balance>=0), enabled INTEGER NOT NULL DEFAULT 1 CHECK(enabled IN (0,1)), created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE TABLE paper_positions (id INTEGER PRIMARY KEY AUTOINCREMENT, account_id TEXT NOT NULL REFERENCES paper_accounts(id), asset_id TEXT NOT NULL, token_name TEXT, quantity REAL NOT NULL CHECK(quantity>0), avg_entry_price REAL NOT NULL CHECK(avg_entry_price>0), last_price REAL NOT NULL CHECK(last_price>0), cost_basis REAL NOT NULL CHECK(cost_basis>0), opened_at TEXT NOT NULL, updated_at TEXT NOT NULL, UNIQUE(account_id,asset_id));
CREATE TABLE paper_trades (id INTEGER PRIMARY KEY AUTOINCREMENT, account_id TEXT NOT NULL REFERENCES paper_accounts(id), asset_id TEXT NOT NULL, token_name TEXT, side TEXT NOT NULL CHECK(side IN ('buy','sell')), quantity REAL NOT NULL CHECK(quantity>0), reference_price REAL NOT NULL CHECK(reference_price>0), fill_price REAL NOT NULL CHECK(fill_price>0), gross_usd REAL NOT NULL, fee_usd REAL NOT NULL, realized_pnl_usd REAL NOT NULL DEFAULT 0, reason TEXT NOT NULL, created_at TEXT NOT NULL, mode TEXT NOT NULL DEFAULT 'paper' CHECK(mode='paper'));
CREATE TABLE paper_activity (id INTEGER PRIMARY KEY AUTOINCREMENT, account_id TEXT NOT NULL REFERENCES paper_accounts(id), event_type TEXT NOT NULL, message TEXT NOT NULL, details_json TEXT NOT NULL DEFAULT '{}', created_at TEXT NOT NULL);
CREATE INDEX idx_paper_positions_account ON paper_positions(account_id);
CREATE INDEX idx_paper_trades_account_time ON paper_trades(account_id,created_at);
CREATE INDEX idx_paper_activity_account_time ON paper_activity(account_id,created_at);
